// Clarity Data Export API は dimension1 パラメータを実質無視し、常に Channel breakdown を返す。
// 過去 6 dim (Channel/Browser/URL/Country/Campaign/OS) 呼びで全て同じ Channel 結果が返っていたため無駄。
// ec_ux_health は Clarity API 仕様変更 (Browser key 消失 + Traffic/EngagementTime/ScrollDepth metric 停止)
// で 5/25 以降 0 rows のまま稼働、廃止済 → 1 call/day (Channel dim) に集約 (API quota 節約)。
return [
  { json: { dimension_set: 'Channel', q1: 'Channel', q2: '', q3: '' } }
];

// Clarity response: [{ metricName, information: [{ ...metrics + dimension values }] }, ...]
// HTTP node が array response を split することがあるため、pairedItem.item で
// 各 input をどの init config 由来か判定して group してから処理する。
//
// Clarity API は 1 日あたり実質 5-7 calls しか叩けない (doc: 10/day) ため、6 dim 呼びでも
// 末尾数件が 429 で落ちることがある。HTTP node は onError=continueRegularOutput を設定済で、
// 失敗 item が main output に流れてくる。下記で error item を判別して skip し、success 分のみ
// BQ insert する (部分成功許容)。全 dim 失敗の日は BQ 0 件で許容 = 現状と同等。

const initItems = $('Init: Dimension Configs').all();
const now = new Date().toISOString();
const nowMs = Date.now();
const todayJST = new Date(nowMs + 9*60*60*1000).toISOString().split('T')[0];
const dataDate = new Date(nowMs + 9*60*60*1000 - 24*60*60*1000).toISOString().split('T')[0];
const rows = [];
const num = (v) => v == null || v === '' ? null : Number(v);

// Group inputs by source init config index (via pairedItem.item)
const inputs = $input.all();
const grouped = new Map(); // initIndex -> [body, ...]
for (let i = 0; i < inputs.length; i++) {
  const body = inputs[i].json;
  // continueRegularOutput 経由で失敗 item が来る場合の skip
  // n8n は失敗時 body に { error: { message, httpCode } } 形式 or message を入れる
  const isError = body && (body.error || body._error
    || (typeof body.httpCode === 'number' && body.httpCode >= 400)
    || (typeof body.message === 'string' && /quota|429|exceeded|too many requests/i.test(body.message)));
  if (isError) {
    console.log('[skip error item ' + i + '] ' + JSON.stringify(body).slice(0, 200));
    continue;
  }
  const p = inputs[i].pairedItem;
  const idx = (p && (Array.isArray(p) ? p[0]?.item : p.item)) ?? i;
  if (!grouped.has(idx)) grouped.set(idx, []);
  grouped.get(idx).push(body);
}

for (const [idx, bodies] of grouped) {
  const cfg = initItems[idx]?.json;
  if (!cfg) continue;
  const dimNames = [cfg.q1, cfg.q2, cfg.q3].filter(x => x);

  const merged = new Map();
  const ensureRow = (entry) => {
    const dimVals = dimNames.map(n => entry?.[n] != null ? String(entry[n]) : null);
    const key = JSON.stringify(dimVals);
    if (!merged.has(key)) {
      merged.set(key, {
        dimension_set:    cfg.dimension_set,
        dimension1_name:  dimNames[0] || null,
        dimension1_value: dimVals[0]  || null,
        dimension2_name:  dimNames[1] || null,
        dimension2_value: dimVals[1]  || null,
        dimension3_name:  dimNames[2] || null,
        dimension3_value: dimVals[2]  || null,
      });
    }
    return merged.get(key);
  };

  // 各 input は metric 単一 or 配列。両方扱う。
  const metrics = [];
  for (const body of bodies) {
    if (Array.isArray(body)) metrics.push(...body);
    else if (Array.isArray(body?.data)) metrics.push(...body.data);
    else if (body && body.metricName) metrics.push(body);
  }

  for (const m of metrics) {
    const metricName = (m.metricName || '').toString();
    const info = Array.isArray(m.information) ? m.information : [];
    for (const entry of info) {
      const row = ensureRow(entry);
      switch (metricName) {
        case 'Traffic':
          row.traffic_total_session_count     = num(entry.totalSessionCount);
          row.traffic_total_bot_session_count = num(entry.totalBotSessionCount);
          row.traffic_distinct_user_count     = num(entry.distinctUserCount);
          row.traffic_pages_per_session       = num(entry.PagesPerSessionPercentage ?? entry.pagesPerSessionPercentage);
          break;
        case 'EngagementTime':
          row.engagement_active_time_seconds = num(entry.activeTime ?? entry.activeTimeInSeconds);
          row.engagement_total_time_seconds  = num(entry.totalTime  ?? entry.totalTimeInSeconds);
          break;
        case 'ScrollDepth':
          row.scroll_depth_percentage = num(entry.averageScrollDepth ?? entry.scrollDepth);
          break;
        case 'RageClickCount':
        case 'RageClicks':
          row.rage_click_count = num(entry.subTotal ?? entry.rageClickCount);
          break;
        case 'DeadClickCount':
        case 'DeadClicks':
          row.dead_click_count = num(entry.subTotal ?? entry.deadClickCount);
          break;
        case 'ExcessiveScroll':
        case 'ExcessiveScrollCount':
          row.excessive_scroll_count = num(entry.subTotal ?? entry.excessiveScrollCount);
          break;
        case 'QuickbackClick':
        case 'QuickBackCount':
          row.quick_back_count = num(entry.subTotal ?? entry.quickBackCount);
          break;
        case 'ScriptError':
        case 'ScriptErrorCount':
          row.script_error_count = num(entry.subTotal ?? entry.scriptErrorCount);
          break;
        case 'ErrorClick':
        case 'ErrorClickCount':
          row.error_click_count = num(entry.subTotal ?? entry.errorClickCount);
          break;
      }
    }
  }

  const payload = JSON.stringify(bodies);
  const cappedPayload = payload.length > 100000 ? payload.slice(0, 100000) : payload;
  for (const row of merged.values()) {
    rows.push({
      snapshot_date: todayJST,
      data_date:     dataDate,
      ...row,
      raw_payload:   cappedPayload,
      inserted_at:   now
    });
  }
}

return rows.map(json => ({ json }));
